def main(root):
    e=root/'source_evidence'; ledger=e/'BM_Completeness_Readiness_2026-10-23.json'
    data=json.loads(ledger.read_text()); source={s['id']:s for s in data['sources']}
    used=['R','I','B18','B20','B21']; files={}
    for k in used:
        s=source[k];p=e/unquote(Path(urlparse(s['url']).path).name)
        raw=p.read_bytes();assert hashlib.sha256(raw).hexdigest()==s['sha256']
        files[k]=(p,raw.decode('utf-8').splitlines(keepends=True))
    rows=[r for r in data['inventory'] if r['framework']=='BM' and r['classification']=='Theorem'
          and not r['dependencies'] and not re.fullmatch(r'T(0[1-9]|[1-4][0-9]|5[0-5])',r['id'])]
    assert len(rows)==128
    result=[]
    for r in rows:
        m=re.match(r'([A-Za-z0-9]+): (.*?) \(line (\d+)\)',r['clause'])
        assert m,r['id'];sid,description,n=m.group(1),m.group(2),int(m.group(3));p,lines=files[sid]
        assert 1<=n<=len(lines),r['id']
        start=n-1
        while start>0 and not re.match(r'^#{1,6}\s',lines[start]):start-=1
        heading=lines[start].rstrip('\n')
        match=re.match(r'^(#{1,6})\s',heading)
        assert match,(r['id'],n)
        level=len(match.group(1));end=start+1
        while end<len(lines):
            h=re.match(r'^(#{1,6})\s',lines[end])
            if h and len(h.group(1))<=level:break
            end+=1
        segment=''.join(lines[start:end]).encode()
        direct=REVIEWS.get(r['id'])
        result.append({'id':r['id'],'name':r['name'],'source':sid,'source_file':p.name,
                       'stated_anchor_line':n,'section_start_line':start+1,'section_end_line':end,
                       'anchor_text':lines[n-1].strip(),'heading':heading,
                       'section_sha256':hashlib.sha256(segment).hexdigest(),
                       'secondary_source_note':'B18 contains the later resolved result; R records the earlier open question' if r['id'] in ['B-OPEN-Correlated','B-OPEN-Frag'] else None,
                       'review_status':'manual internal proof-basis review' if direct else 'source locator only; dependency and proof review remain open',
                       'internal_review':direct})
    assert set(REVIEWS)<=set(r['id'] for r in result)
    # All declared direct references must exist in the original inventory.
    ids={r['id'] for r in data['inventory']}
    for r in result:
        if r['internal_review']:
            assert all(d in ids for d in r['internal_review']['direct_BM_results'])
    out={'date':'2026-10-29','scope':'BM theorem rows with previously empty dependency fields, excluding T01–T55',
         'base_inventory_sha256':hashlib.sha256(ledger.read_bytes()).hexdigest(),
         'source_locators':len(result),'new_manually_reviewed':len(REVIEWS),'still_requiring_dependency_review':len(result)-len(REVIEWS),
         'interpretation':'A source locator is not proof validation. Prior nonempty dependency lists also remain to be checked.',
         'rows':result}
    (root/'BM_Source_Trace_2026-10-29.json').write_text(json.dumps(out,indent=2)+'\n')
    print(json.dumps({k:out[k] for k in ['source_locators','new_manually_reviewed','still_requiring_dependency_review']},indent=2))


if __name__=='__main__':main(Path(sys.argv[1] if len(sys.argv)>1 else '.').resolve())
